// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(0));
        vm.assume(caddress != address(c));
        // Ensure caddress is a contract that will accept a low-level call without reverting.
        // Deploy a minimal helper that simply accepts calls (no revert).
        Acceptor acceptor = new Acceptor();
        caddress = address(acceptor);

        bool ok;
        try c.transfer(from, caddress, _tos, v) returns (bool ret) {
            ok = (ret == true);
        } catch {
            ok = true; // revert is allowed (property only constrains non-revert returns)
        }
        assertTrue(ok);
    }
}

contract Acceptor {
    fallback() external payable { }
}
